    trapExamples: [{ question: "0.4＋0.8は？", wrongAnswer: "0.12", trapExplanation: "4＋8＝12を そのまま 小数点の 右に 書いて しまった。", correctAnswer: "1.2", correctExplanation: "0.1が 12こ分。10こで 1だから 1と 2こ分で 1.2。" }],
