    trapExamples: [{ question: "家を 8時に 出て、8時25分に 学校に 着きました。かかった 時間は？", wrongAnswer: "8時25分", trapExplanation: "着いた 時こくを 答えて しまった。聞かれて いるのは どれだけ かかったか。", correctAnswer: "25分間", correctExplanation: "8時から 8時25分までの 長さが 25分間。" }],
