    trapExamples: [{ question: "午後3時を 24時間の 言い方で あらわすと？", wrongAnswer: "3時", trapExplanation: "午前の 3時との ちがいが 分からなく なる。", correctAnswer: "15時", correctExplanation: "午後は 12を たす。3＋12＝15時。" }],
