    trapExamples: [{ question: "8時40分に 家を 出て、30分 かけて 学校に 着きました。着いた 時こくは？", wrongAnswer: "8時70分", trapExplanation: "分を そのまま たした。60を こえたら 1時間 くり上げる。", correctAnswer: "9時10分", correctExplanation: "8時40分から 9時まで 20分、のこり 10分。9時10分。" }],
